// main/app_dashboard/dashboard_logos.h
// Provider logos shown on the AGENTS page. The pixel data is generated by
// tools/convert_logo.py from assets/images/agent-*-logo.svg; do not edit the C file
// by hand. Both descriptors are LV_COLOR_FORMAT_RGB565A8, 32x32, about 3 KB of flash
// each and no RAM, because they are drawn straight from flash.
#pragma once

#include "lvgl.h"

extern const lv_image_dsc_t dashboard_logo_pi;
extern const lv_image_dsc_t dashboard_logo_dsh;

// Pick the logo for a provider id as it appears in the frame's `pv` field.
// Returns NULL for an unknown provider, and the caller then shows no logo rather than
// a wrong one.
const lv_image_dsc_t *dashboard_provider_logo(const char *provider);
